import { createElement } from "../../../core/dom/create.js";
import { setStyles } from "../../../core/dom/utils.js";
import { createFormValue } from "../../../core/dom/form-value.js";
export const withDom = (config) => (component) => {
    const getClass = (className) => component.getClass(className);
    const min = config.min || 0;
    const max = config.max || 100;
    const value = config.value !== undefined ? config.value : min;
    const isDisabled = config.disabled === true;
    const formatter = config.valueFormatter || ((val) => val.toString());
    const valuePercent = ((value - min) / (max - min)) * 100;
    const container = createElement({
        tag: "div",
        className: getClass("slider__container"),
        container: component.element,
    });
    setStyles(container, {
        position: "relative",
    });
    const label = config.label || "";
    const handleLabel = config.range && label ? `${label} minimum` : label;
    const secondHandleLabel = label ? `${label} maximum` : "";
    const handleAttributes = {
        role: "slider",
        "aria-valuemin": String(min),
        "aria-valuemax": String(max),
        "aria-valuenow": String(value),
        "aria-orientation": config.orientation === "vertical" ? "vertical" : "horizontal",
        tabindex: isDisabled ? "-1" : "0",
        "aria-disabled": isDisabled ? "true" : "false",
        "data-value": String(value),
        "data-handle-index": "0",
    };
    if (handleLabel) {
        handleAttributes["aria-label"] = handleLabel;
    }
    const handle = createElement({
        tag: "div",
        className: getClass("slider__handle"),
        attributes: handleAttributes,
        container: container,
    });
    setStyles(handle, {
        left: `${valuePercent}%`,
    });
    const valueBubble = createElement({
        tag: "div",
        className: getClass("slider__value"),
        attributes: {
            "aria-hidden": "true",
            "data-handle-index": "0",
        },
        text: formatter(value),
        container: container,
    });
    setStyles(valueBubble, {
        left: `${valuePercent}%`,
    });
    let secondHandle;
    let secondValueBubble;
    if (config.range) {
        const secondValue = config.secondValue !== undefined ? config.secondValue : max;
        const secondValuePercent = ((secondValue - min) / (max - min)) * 100;
        const secondHandleAttributes = {
            role: "slider",
            "aria-valuemin": String(min),
            "aria-valuemax": String(max),
            "aria-valuenow": String(secondValue),
            "aria-orientation": config.orientation === "vertical" ? "vertical" : "horizontal",
            tabindex: isDisabled ? "-1" : "0",
            "aria-disabled": isDisabled ? "true" : "false",
            "data-value": String(secondValue),
            "data-handle-index": "1",
        };
        if (secondHandleLabel) {
            secondHandleAttributes["aria-label"] = secondHandleLabel;
        }
        secondHandle = createElement({
            tag: "div",
            className: getClass("slider__handle"),
            attributes: secondHandleAttributes,
            container: container,
        });
        setStyles(secondHandle, {
            left: `${secondValuePercent}%`,
        });
        secondValueBubble = createElement({
            tag: "div",
            className: getClass("slider__value"),
            attributes: {
                "aria-hidden": "true",
                "data-handle-index": "1",
            },
            text: formatter(secondValue),
            container: container,
        });
        setStyles(secondValueBubble, {
            left: `${secondValuePercent}%`,
        });
    }
    const name = config.name;
    const formFields = name
        ? [
            createFormValue(component.element, name, String(value), isDisabled),
            config.range
                ? createFormValue(component.element, `${name}-end`, String(config.secondValue ?? max), isDisabled)
                : null,
        ]
        : null;
    return {
        ...component,
        container,
        handle,
        valueBubble,
        secondHandle,
        secondValueBubble,
        formFields,
        getContainer: () => container,
        getHandle: () => handle,
        getValueBubble: () => valueBubble,
        getSecondHandle: () => secondHandle || null,
        getSecondValueBubble: () => secondValueBubble || null,
    };
};
